using var client = AudraClient.CreateFromEnvironment();

var request = global::System.Text.Json.JsonSerializer.Deserialize<global::Audra.SpeechRequest>(
    @"{
  ""model"": ""audra-essential"",
  ""voice"": ""june"",
  ""text"": ""Hello world"",
  ""format"": ""mp3"",
  ""speed"": 1.0
}")!;

var response = await client.Speech.CreateSpeechAsync(
    request: request
);

